  const[aiQ,setAiQ]=useState<any[]>([]);const[aiIdx,setAiIdx]=useState(0);const[aiAns,setAiAns]=useState<Record<string,string>>({});const[genSummary,setGenSummary]=useState("");const[feedback,setFeedback]=useState("");
